export const AWARD_ICON_CATEGORIES = Array.from(new Set(AWARD_ICONS.map(i => i.category)))

export function findAwardIcon(id: string | null | undefined): AwardIcon | undefined {
    if (!id) return undefined
    return AWARD_ICONS.find(i => i.id === id)
}

// Fetch the SVG body for an icon. Featured icons resolve instantly from
// the inlined map; everything else is lazy-loaded from awards-icons/{id}.svg.
const svgCache: Record<string, string> = { ...FEATURED_SVGS }
export async function getAwardIconSvg(id: string): Promise<string | null> {
    if (svgCache[id]) return svgCache[id]
    try {
        const r = await fetch("awards-icons/" + id + ".svg")
        if (!r.ok) return null
        const svg = await r.text()
        svgCache[id] = svg
        return svg
    } catch {
        return null
    }
}

// Default-award slug -> icon id mapping (stable seeds for new sessions)
export const DEFAULT_AWARD_ICONS: Record<string, string> = {
    'best-performance': 'game-icons__trophy-cup',
    'singer-of-the-night': 'game-icons__microphone',
    'best-duo-group': 'game-icons__high-five',
}
